steps.command:
cat > /srv/ipc/ipc.pl <<'PERLEOF'
use strict; use warnings;
use IO::Socket::UNIX;
my $S = "/run/app/app.sock";
unlink $S if -e $S;
my $srv = IO::Socket::UNIX->new(Local => $S, Type => SOCK_STREAM, Listen => 4)
    or die "bind: $!";
my $pid = fork(); die "fork: $!" unless defined $pid;
if (!$pid) {
    select(undef, undef, undef, 0.3);
    for my $i (0..2) {
        my $c = IO::Socket::UNIX->new(Peer => $S, Type => SOCK_STREAM) or die "connect: $!";
        print $c "status $i";
        shutdown($c, 1);
        my $resp = <$c> // '';
        print "worker got $resp\n";
        close $c;
    }
    exit 0;
}
for my $i (0..2) {
    my $conn = $srv->accept() or next;
    my $msg = <$conn> // '';
    print $conn "ack:$msg";
    close $conn;
}
waitpid($pid, 0);
close $srv;
unlink $S;
print "ipc round trip done\n";
PERLEOF
perl -c /srv/ipc/ipc.pl
